'use strict';
// Galaga (Namco, 1981) - "galaga" (Namco rev. B) MAME romset
const ROM_DATA = {
  // gg1_1b.3p (CPU1 @ 0x0000)
  cpu1_0: "",
  // gg1_2b.3m (CPU1 @ 0x1000)
  cpu1_1: "",
  // gg1_3.2m (CPU1 @ 0x2000)
  cpu1_2: "",
  // gg1_4b.2l (CPU1 @ 0x3000)
  cpu1_3: "",
  // gg1_5b.3f (CPU2 @ 0x0000)
  cpu2_0: "",
  // gg1_7b.2c (CPU3 @ 0x0000)
  cpu3_0: "",
  // gg1_9.4l (tile gfx)
  gfx1: "",
  // gg1_11.4d (sprite gfx @ 0x0000)
  gfx2_0: "",
  // gg1_10.4f (sprite gfx @ 0x1000)
  gfx2_1: "",
  // prom-5.5n (palette PROM)
  prom_pal: "9gc/Jy/H+O0WOCHYxMCgAPYHPycAx/joADgA2MXAAAA=",
  // prom-4.2n (char color lookup PROM)
  prom_char: "",
  // prom-3.1c (sprite color lookup PROM)
  prom_spr: "",
  // prom-1.1d (WSG waveform PROM)
  prom_wsg: "",
};

function decodeCpuRom(keys) {
  const chunks = keys.map(k => atob(ROM_DATA[k]));
  const rom = new Uint8Array(0x4000).fill(0xFF); // unpopulated ROM reads as erased-EPROM 0xFF
  let off = 0;
  for (const bin of chunks) {
    for (let i = 0; i < bin.length; i++) rom[off + i] = bin.charCodeAt(i);
    off += bin.length;
  }
  return rom;
}

function decodeBytes(key) {
  const bin = atob(ROM_DATA[key]);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function decodeConcat(keys) {
  const chunks = keys.map(k => atob(ROM_DATA[k]));
  const total = chunks.reduce((n, b) => n + b.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const bin of chunks) {
    for (let i = 0; i < bin.length; i++) out[off + i] = bin.charCodeAt(i);
    off += bin.length;
  }
  return out;
}

function decodeGalagaRoms() {
  return {
    cpu1: decodeCpuRom(['cpu1_0', 'cpu1_1', 'cpu1_2', 'cpu1_3']),
    cpu2: decodeCpuRom(['cpu2_0']),
    cpu3: decodeCpuRom(['cpu3_0']),
    gfxTiles: decodeBytes('gfx1'),
    gfxSprites: decodeConcat(['gfx2_0', 'gfx2_1']),
    // proms region layout matches MAME's ROM_REGION load order exactly:
    // palette(0x20) + char lookup(0x100) + sprite lookup(0x100)
    proms: decodeConcat(['prom_pal', 'prom_char', 'prom_spr']),
    wsgProm: decodeBytes('prom_wsg'),
  };
}
